+function setAppUpdateFallback(command, visible = false) {
+  const fallback = document.getElementById('app-update-fallback');
+  const code = document.getElementById('app-update-command');
+  if (!fallback || !code) return;
+  code.textContent = command || 'git pull --ff-only origin main && uv sync';
+  fallback.classList.toggle('visible', Boolean(visible));
+}
+
+function appUpdateButtonLabel(version) {
+  if (!version) return 'Checking...';
+  if (version.status === 'current') return 'Up to Date';
+  if (version.status === 'update_available') return 'Update App';
+  if (version.status === 'blocked_dirty') return 'Blocked';
+  if (version.status === 'manual_required') return 'Manual Update';
+  return 'Check Failed';
+}
+
+function renderAppVersion(version, options = {}) {
+  const button = document.getElementById('app-update-button');
+  const status = document.getElementById('app-update-status');
+  if (!button || !status) return;
+
+  currentAppVersion = version || currentAppVersion;
+  const fallbackCommand = currentAppVersion?.fallback_command || 'git pull --ff-only origin main && uv sync';
+  const canUpdate = currentAppVersion?.status === 'update_available';
+  button.dataset.updateStatus = options.running && canUpdate ? 'update_available' : currentAppVersion?.status || 'checking';
+  button.disabled = Boolean(options.running || !canUpdate);
+  button.textContent = options.running ? 'Updating...' : appUpdateButtonLabel(currentAppVersion);
+  button.title = currentAppVersion
+    ? `${currentAppVersion.message || ''} Current ${currentAppVersion.branch || 'branch'}@${currentAppVersion.sha || 'unknown'}; latest ${currentAppVersion.target_ref || 'origin/main'}@${currentAppVersion.target_sha || 'unknown'}.`.trim()
+    : 'Checking latest main branch.';
+  status.className = `app-update-status ${options.tone || ''}`.trim();
+  status.textContent = options.message || currentAppVersion?.message || 'Checking latest main branch...';
+  setAppUpdateFallback(fallbackCommand, Boolean(options.showFallback));
+}
+
+async function loadAppVersion() {
+  renderAppVersion(null, { message: 'Checking app version...' });
+  try {
+    const response = await fetch('/api/app-version', {
+      headers: { 'X-Dashboard-Update': '1' },
+    });
+    const version = await response.json();
+    renderAppVersion(version);
+  } catch (error) {
+    console.error('app version', error);
+    renderAppVersion(currentAppVersion, {
+      message: 'Unable to check app version.',
+      tone: 'error',
+      showFallback: true,
+    });
+  }
+}
+
+async function updateApp() {
+  renderAppVersion(currentAppVersion, { running: true, message: 'Updating...', tone: '' });
+  try {
+    const response = await fetch('/api/update', {
+      method: 'POST',
+      headers: { 'X-Dashboard-Update': '1' },
+    });
+    const result = await response.json().catch(() => ({}));
+    const fallbackCommand = result.fallback_command || currentAppVersion?.fallback_command || 'git pull --ff-only origin main && uv sync';
+    setAppUpdateFallback(fallbackCommand, false);
+    if (response.ok && result.status === 'updated') {
+      renderAppVersion({ ...currentAppVersion, sha: result.new_sha, target_sha: result.target_sha, status: 'current', update_available: false, dirty: false }, {
+        message: `Updated to ${result.new_sha}. Restart required.`,
+        tone: 'success',
+      });
+      return;
+    }
+    if (response.ok && result.status === 'already_current') {
+      renderAppVersion({ ...currentAppVersion, sha: result.new_sha, target_sha: result.target_sha, status: 'current', update_available: false }, {
+        message: 'Already up to date.',
+        tone: 'success',
+      });
+      return;
+    }
+    if (result.status === 'local_changes') {
+      renderAppVersion({
+        ...currentAppVersion,
+        status: 'blocked_dirty',
+        update_available: true,
+        dirty: true,
+        target_sha: result.target_sha || currentAppVersion?.target_sha,
+      }, {
+        message: 'Local changes detected. Update manually to avoid overwriting work.',
+        tone: 'warning',
+      });
+      return;
+    }
+    renderAppVersion(currentAppVersion, {
+      message: 'Update failed. Run: git pull --ff-only origin main && uv sync',
+      tone: 'error',
+      showFallback: true,
+    });
+  } catch (error) {
+    console.error('update app', error);
+    renderAppVersion(currentAppVersion, {
+      message: 'Update failed. Run: git pull --ff-only origin main && uv sync',
+      tone: 'error',
+      showFallback: true,
+    });
+  }
+}
